def transform(grid):
    """Partition occupied cells into 2x2 squares and 3-cell L tiles.

    Full squares become color 1. For an L tile, the color identifies its
    missing corner: top-left=2, bottom-left=3, top-right=4, bottom-right=5.
    """
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    options = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if box <= occupied:
                options.append((frozenset(box), 1))
            for missing in box:
                cells = box - {missing}
                if cells <= occupied:
                    # TL, BL, TR, BR encode 2, 3, 4, 5 respectively.
                    color = {(r, c): 2, (r + 1, c): 3,
                             (r, c + 1): 4, (r + 1, c + 1): 5}[missing]
                    options.append((frozenset(cells), color))
    by_cell = {p: [] for p in occupied}
    for cells, color in options:
        for p in cells:
            by_cell[p].append((cells, color))
    # Prefer full 2x2 tiles, then L's with consistent deterministic corner order.
    for p in by_cell:
        by_cell[p].sort(key=lambda item: (0 if item[1] == 1 else 1, item[1], sorted(item[0])))

    def search(remaining, chosen):
        if not remaining:
            out = [[0] * w for _ in range(h)]
            for cells, color in chosen:
                for r, c in cells:
                    out[r][c] = color
            return out
        p = min(remaining)
        for cells, color in by_cell[p]:
            if cells <= remaining:
                result = search(remaining - cells, chosen + [(cells, color)])
                if result is not None:
                    return result
        return None

    result = search(occupied, [])
    if result is None:
        raise ValueError('occupied cells cannot be tiled by 2x2 squares and L triominoes')
    return result
